def cmp_semver(a: str, b: str) -> int:
    def split_version(v: str):
        # Remove build metadata
        v = v.split('+', 1)[0]
        # Split into core and pre‑release
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        # Split core into major, minor, patch
        parts = list(map(int, core.split('.')))
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: {v}")
        return parts, pre

    core_a, pre_a = split_version(a)
    core_b, pre_b = split_version(b)

    # Compare numeric parts
    for i in range(3):
        if core_a[i] < core_b[i]:
            return -1
        if core_a[i] > core_b[i]:
            return 1

    # Numeric parts are equal, handle pre‑release
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    # Both have pre‑release
    ids_a = pre_a.split('.')
    ids_b = pre_b.split('.')
    min_len = min(len(ids_a), len(ids_b))

    for i in range(min_len):
        a_id = ids_a[i]
        b_id = ids_b[i]
        a_is_num = a_id.isdigit()
        b_is_num = b_id.isdigit()

        if a_is_num and b_is_num:
            a_val = int(a_id)
            b_val = int(b_id)
            if a_val < b_val:
                return -1
            if a_val > b_val:
                return 1
        else:
            # At least one is non‑numeric; compare as strings
            if a_id < b_id:
                return -1
            if a_id > b_id:
                return 1

    # All compared identifiers are equal
    if len(ids_a) < len(ids_b):
        return -1
    if len(ids_a) > len(ids_b):
        return 1
    return 0
