import re

def gitignore_match(pattern: str, path: str) -> bool:
    # Normalize pattern
    if pattern.endswith('/'):
        is_dir_pattern = True
        pattern = pattern[:-1]
    else:
        is_dir_pattern = False

    # Determine if pattern is anchored at root
    if pattern.startswith('/'):
        anchored = True
        pattern = pattern[1:]
    else:
        anchored = False

    # Split path into components (ignore empty parts)
    path_parts = [p for p in path.split('/') if p]

    # Handle directory pattern
    if is_dir_pattern:
        if not path_parts:
            return False
        # The last component must match the pattern
        last = path_parts[-1]
        if not _match_pattern(pattern, last):
            return False
        # If pattern contains a slash, it must be anchored at root
        if '/' in pattern:
            if not anchored:
                return False
            # The whole path must be exactly the pattern (no extra components)
            if len(path_parts) != len(pattern.split('/')):
                return False
        else:
            # No slash in pattern: matches any depth, but only if the last component matches
            # (already checked)
            pass
        return True

    # No directory pattern
    if '/' in pattern:
        if not anchored:
            return False
        # Split pattern into components
        pat_parts = pattern.split('/')
        if len(pat_parts) > len(path_parts):
            return False
        for i, pat_part in enumerate(pat_parts):
            if not _match_pattern(pat_part, path_parts[i]):
                return False
        return True
    else:
        # Simple pattern: matches any depth
        for part in path_parts:
            if _match_pattern(pattern, part):
                return True
        return False


def _match_pattern(pat: str, name: str) -> bool:
    # Convert gitignore pattern to regex
    # Escape special regex characters except *, ?, [, ]
    regex = re.escape(pat)
    # Replace escaped * with .* but only if not escaped by a backslash
    # Since we escaped everything, we need to unescape the ones we want to treat specially
    # We'll do it manually:
    regex = regex.replace(r'\*', '.*')
    regex = regex.replace(r'\?', '.')
    # Handle character classes: [abc] is already correct after escaping
    # But we need to ensure that the dot inside [] is not interpreted as any character
    # The regex module treats [.] as a literal dot, so it's fine.
    # However, we must ensure that the pattern does not contain a slash, which it won't.
    # Add start and end anchors
    regex = f'^{regex}$'
    return bool(re.fullmatch(regex, name))
