def parse_range(header, size):
    if not header.startswith('bytes='):
        return None
    ranges_str = header[6:].strip()
    if not ranges_str:
        return None

    result = []
    for part in ranges_str.split(','):
        part = part.strip()
        if not part:
            continue

        if '-' not in part:
            return None

        start_str, end_str = part.split('-', 1)

        # suffix range: "-500"
        if start_str == '':
            try:
                suffix = int(end_str)
            except ValueError:
                return None
            if suffix <= 0:
                return None
            start = max(0, size - suffix)
            end = size - 1
            if start > end:
                return None
            result.append((start, end))
            continue

        # normal range: "0-499" or "500-"
        try:
            start = int(start_str)
        except ValueError:
            return None

        if end_str == '':
            # "500-"
            if start >= size:
                return None
            end = size - 1
        else:
            try:
                end = int(end_str)
            except ValueError:
                return None
            if end < start:
                return None
            if end >= size:
                end = size - 1

        if start >= size:
            return None
        if start > end:
            return None

        result.append((start, end))

    if not result:
        return None
    return result
