def unified_diff(a, b, context=3):
    if a == b:
        return []

    # ---------- longest common subsequence ----------
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # backtrack to obtain one LCS
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            lcs.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    lcs.reverse()

    # ---------- map each line to its LCS index ----------
    a_idx = {}
    b_idx = {}
    for k, line in enumerate(lcs):
        a_idx[line] = k
        b_idx[line] = k

    # ---------- build diff operations ----------
    ops = []
    i = j = 0
    while i < m or j < n:
        if i < m and j < n and a[i] == b[j]:
            i += 1
            j += 1
        elif i < m and (j >= n or a[i] not in b_idx or b_idx[a[i]] < j):
            ops.append(('del', i))
            i += 1
        elif j < n and (i >= m or b[j] not in a_idx or a_idx[b[j]] < i):
            ops.append(('add', j))
            j += 1
        else:
            # both have the line in LCS at the same position
            i += 1
            j += 1

    # ---------- group operations into hunks ----------
    hunks = []
    i = j = 0
    while i < len(ops) or j < len(ops):
        # find next operation
        while i < len(ops) and ops[i][0] != 'add':
            i += 1
        while j < len(ops) and ops[j][0] != 'del':
            j += 1
        if i >= len(ops) and j >= len(ops):
            break

        # start of hunk
        if i < len(ops):
            start_a = ops[i][1]
        else:
            start_a = 0
        if j < len(ops):
            start_b = ops[j][1]
        else:
            start_b = 0

        # collect operations until a gap > context
        del_ops = []
        add_ops = []
        while i < len(ops) or j < len(ops):
            # check gap
            if del_ops and add_ops:
                gap_a = ops[i][1] - del_ops[-1][1] - 1
                gap_b = ops[j][1] - add_ops[-1][1] - 1
                if gap_a > context or gap_b > context:
                    break
            # take next operation
            if i < len(ops) and (j >= len(ops) or ops[i][0] == 'del'):
                del_ops.append(ops[i])
                i += 1
            elif j < len(ops) and (i >= len(ops) or ops[j][0] == 'add'):
                add_ops.append(ops[j])
                j += 1
            else:
                # both have an operation of the same type – should not happen
                break

        # end of hunk
        if del_ops:
            end_a = del_ops[-1][1]
        else:
            end_a = start_a
        if add_ops:
            end_b = add_ops[-1][1]
        else:
            end_b = start_b

        # context before
        ctx_a_start = max(0, start_a - context)
        ctx_b_start = max(0, start_b - context)
        ctx_a_len = start_a - ctx_a_start
        ctx_b_len = start_b - ctx_b_start

        # context after
        ctx_a_end = min(m, end_a + context + 1)
        ctx_b_end = min(n, end_b + context + 1)
        ctx_a_len2 = ctx_a_end - end_a
        ctx_b_len2 = ctx_b_end - end_b

        # build hunk lines
        hunk_lines = []
        # context before
        for k in range(ctx_a_start, start_a):
            hunk_lines.append(' ' + a[k])
        # context after
        for k in range(end_a + 1, ctx_a_end):
            hunk_lines.append(' ' + a[k])
        # header
        hunk_lines.insert(0, f'@@ -{start_a + 1},{ctx_a_len} +{start_b + 1},{ctx_b_len} @@')
        # deletions
        for _, pos in del_ops:
            hunk_lines.append('-' + a[pos])
        # additions
        for _, pos in add_ops:
            hunk_lines.append('+' + b[pos])
        # context after (again)
        for k in range(end_b + 1, ctx_b_end):
            hunk_lines.append(' ' + b[k])

        hunks.append(hunk_lines)

    # ---------- flatten ----------
    result = []
    for h in hunks:
        result.extend(h)
    return result
