import re
from datetime import datetime, timedelta
from typing import List, Tuple, Union

def _parse_field(field: str) -> List[int]:
    """Parse a single cron field into a sorted list of allowed values."""
    if not field:
        raise ValueError("Empty field")
    parts = field.split(',')
    values = set()
    for part in parts:
        if part == '*':
            continue
        if '/' in part:
            base, step_str = part.split('/')
            step = int(step_str)
            if step <= 0:
                raise ValueError(f"Invalid step {step}")
            if base == '*':
                # wildcard step: 0, step, 2*step, ...
                for v in range(0, 60, step):
                    values.add(v)
            else:
                # step with base range
                if '-' in base:
                    start_str, end_str = base.split('-')
                    start, end = int(start_str), int(end_str)
                else:
                    start = end = int(base)
                if start > end:
                    raise ValueError(f"Invalid range {base}")
                for v in range(start, end + 1, step):
                    values.add(v)
        elif '-' in part:
            start_str, end_str = part.split('-')
            start, end = int(start_str), int(end_str)
            if start > end:
                raise ValueError(f"Invalid range {part}")
            for v in range(start, end + 1):
                values.add(v)
        else:
            # single number
            v = int(part)
            values.add(v)
    return sorted(values)

def _next_in_field(values: List[int], start: int) -> int:
    """Return the smallest value >= start, or None if none exists."""
    for v in values:
        if v >= start:
            return v
    return None

def next_fire(expr: str, after: datetime) -> datetime:
    """
    Return the next datetime strictly after `after` at which the 5‑field cron
    expression fires. Seconds and microseconds are zero.
    """
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    # Parse each field
    minute_vals = _parse_field(fields[0])
    hour_vals   = _parse_field(fields[1])
    day_vals    = _parse_field(fields[2])
    month_vals  = _parse_field(fields[3])
    dow_vals    = _parse_field(fields[4])

    # Basic validation of ranges
    for name, vals, minv, maxv in [
        ("minute", minute_vals, 0, 59),
        ("hour",   hour_vals,   0, 23),
        ("day",    day_vals,    1, 31),
        ("month",  month_vals,  1, 12),
        ("dow",    dow_vals,    0, 6)
