        elif tok_type == 'OP' and tok_val == '(':
            op_stack.append(('OP', tok_val))
        elif tok_type == 'OP' and tok_val == ')':
            while op_stack and op_stack[-1][0] != 'OP' or op_stack[-1][1] != '(':
                output.append(op_stack.pop())
            if not op_stack or op_stack[-1][1] != '(':
                raise ValueError("Mismatched parentheses")
            op_stack.pop()  # discard '('
        elif tok_type == 'OP':
