            while op_stack:
                top_type, top_val = op_stack[-1]
                if top_type == 'OP':
                    if (top_val in right_assoc and precedence[top_val] > precedence[tok_val]) or \
                       (top_val not in right_assoc and precedence[top_val] >= precedence[tok_val]):
                        output.append(op_stack.pop())
