                    raise ValueError("Insufficient operands for binary operator")
                b = stack.pop()
                a = stack.pop()
                if val == '+':
                    res = a + b
                elif val == '-':
                    res = a - b
                elif val == '*':
                    res = a * b
                elif val == '/':
                    res = a / b
                elif val == '%':
                    res = a % b
                elif val == '**':
                    res = a ** b
                else:
                    raise ValueError(f"Unsupported operator {val}")
                stack.append(res)
