import heapq
from typing import List

def window_medians(a: List[float], k: int) -> List[float]:
    n = len(a)
    if k > n or k == 0:
        return []

    # max‑heap (store negatives) and min‑heap
    left = []   # max‑heap
    right = []  # min‑heap
    medians = []

    for i, x in enumerate(a):
        # insert x
        if not left or x <= -left[0]:
            heapq.heappush(left, -x)
        else:
            heapq.heappush(right, x)

        # balance sizes: left may have at most one more element than right
        if len(left) > len(right) + 1:
            heapq.heappush(right, -heapq.heappop(left))
        elif len(right) > len(left):
            heapq.heappush(left, -heapq.heappop(right))

        # remove element that slides out of the window
        if i >= k:
            out = a[i - k]
            if out <= -left[0]:
                # remove from left heap
                left.remove(-out)
                heapq.heapify(left)
            else:
                right.remove(out)
                heapq.heapify(right)

            # rebalance after removal
            if len(left) > len(right) + 1:
                heapq.heappush(right, -heapq.heappop(left))
            elif len(right) > len(left):
                heapq.heappush(left, -heapq.heappop(right))

        # record median when the first full window is ready
        if i >= k - 1:
            if k % 2 == 1:
                median = float(-left[0])
            else:
                median = (-left[0] + right[0]) / 2.0
            medians.append(median)

    return medians
