class RollbackDSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.comp_cnt = n
        self.stack = []  # each entry: (child, parent, old_size_of_parent)

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = b, a
        # attach b under a
        self.stack.append((b, a, self.size[a]))
        self.parent[b] = a
        self.size[a] += self.size[b]
        self.comp_cnt -= 1
        return True

    def snapshot(self):
        return len(self.stack)

    def rollback(self, token: int):
        while len(self.stack) > token:
            b, a, old_size = self.stack.pop()
            self.parent[b] = b
            self.size[a] = old_size
            self.comp_cnt += 1

    def components(self) -> int:
        return self.comp_cnt
