def deep_copy(obj, memo=None):
    if memo is None:
        memo = {}
    obj_id = id(obj)
    if obj_id in memo:
        return memo[obj_id]

    if isinstance(obj, dict):
        new_obj = {}
        memo[obj_id] = new_obj
        for k, v in obj.items():
            new_obj[deep_copy(k, memo)] = deep_copy(v, memo)
        return new_obj

    if isinstance(obj, list):
        new_obj = []
        memo[obj_id] = new_obj
        for item in obj:
            new_obj.append(deep_copy(item, memo))
        return new_obj

    if isinstance(obj, set):
        new_obj = set()
        memo[obj_id] = new_obj
        for item in obj:
            new_obj.add(deep_copy(item, memo))
        return new_obj

    if isinstance(obj, tuple):
        new_obj = tuple(deep_copy(item, memo) for item in obj)
        memo[obj_id] = new_obj
        return new_obj

