def to_base(n: int, alphabet: str) -> str:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet characters must be distinct")
    zero_char = alphabet[0]
    if n == 0:
        return zero_char
    sign = '-' if n < 0 else ''
    n = abs(n)
    digits = []
    while n:
        n, rem = divmod(n, len(alphabet))
        digits.append(alphabet[rem])
    return sign + ''.join(reversed(digits))


def from_base(s: str, alphabet: str) -> int:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet characters must be distinct")
    if s == "":
        raise ValueError("Empty string")
    sign = -1 if s[0] == '-' else 1
    if sign == -1:
        s = s[1:]
    if s == "":
        raise ValueError("Empty string after sign removal")
    value = 0
    base = len(alphabet)
    for ch in s:
        if ch not in alphabet:
            raise ValueError(f"Invalid character '{ch}'")
        value = value * base + alphabet.index(ch)
    return sign * value
