function pLimit(n) {
  const queue = [];
  let activeCount = 0;

  const next = async () => {
    if (activeCount >= n || queue.length === 0) {
      return;
    }

    const { fn, resolve, reject } = queue.shift();
    activeCount++;

    try {
      const result = await fn();
      resolve(result);
    } catch (error) {
      reject(error);
    } finally {
      activeCount--;
      next();
    }
  };

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };
}

module.exports = pLimit;
