  const { leading = false, trailing = true } = options;
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let result = null;

  const debounced = function (...args) {
    lastArgs = args;
    lastThis = this;

    const invoke = () => {
      result = fn.apply(lastThis, lastArgs);
      lastArgs = null;
      lastThis = null;
    };

    if (leading && !timeoutId) {
      invoke();
    }

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      if (trailing) {
        invoke();
      }
      timeoutId = null;
    }, wait);
  };

  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      lastArgs = null;
      lastThis = null;
    }
  };

  debounced.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      if (trailing) {
        invoke();
      }
      timeoutId = null;
