    token.replace(/~1/g, '/').replace(/~0/g, '~')
  );

  let current = doc;
  for (let i = 0; i < tokens.length - 1; i++) {
    let token = tokens[i];
    let next = tokens[i + 1];

    if (current == null) {
      current = {};
    }

    if (Array.isArray(current)) {
      if (token === '-') {
        token = String(current.length);
      }
      if (!/^\d+$/.test(token)) {
        throw new Error('Invalid array index');
      }
      let index = parseInt(token, 10);
      if (index >= current.length) {
        current.length = index + 1;
      }
      if (current[index] == null) {
        current[index] = next === undefined ? null : (Array.isArray(next) ? [] : {});
      }
      current = current[index];
    } else {
      if (current[token] == null) {
        current[token] = next === undefined ? null : (Array.isArray(next) ? [] : {});
      }
      current = current[token];
    }
  }

  let lastToken = tokens[tokens.length - 1];
  if (Array.isArray(current)) {
    if (lastToken === '-') {
      current.push(value);
    } else if (/^\d+$/.test(lastToken)) {
      let index = parseInt(lastToken, 10);
      if (index >= current.length) {
