function singleFlight(loader) {
  const inflight = new Map();

  function load(key) {
    let entry = inflight.get(key);
    if (!entry) {
      let resolve, reject;
      const promise = new Promise((res, rej) => {
        resolve = res;
        reject = rej;
      });
      entry = { promise, resolve, reject };
      inflight.set(key, entry);

      loader(key)
        .then(result => {
          entry.resolve(result);
        })
        .catch(err => {
          entry.reject(err);
        })
        .finally(() => {
          inflight.delete(key);
        });
    }
    return entry.promise;
  }

  load.inflight = inflight.size;

  return load;
}

module.exports = singleFlight;
