  let text = strings[0];
  const valuesArray = [];
  let placeholderIndex = 1;

  for (let i = 0; i < values.length; i++) {
    const value = values[i];
    if (value && typeof value === 'object' && value.sqlTag) {
      // INLINE: splice text and merge values with renumbered placeholders
      text += value.text + strings[i + 1];
      for (const v of value.values) {
        valuesArray.push(v);
