    } else if (Array.isArray(value)) {
      // ARRAY: replace with parenthesized list of placeholders
      const placeholders = value.map(() => `$${placeholderIndex++}`).join(', ');
      text += `(${placeholders})` + strings[i + 1];
    } else {
      // SIMPLE: add placeholder and value
      text += `$${placeholderIndex}` + strings[i + 1];
      valuesArray.push(value);
      placeholderIndex++;
    }
  }

