async function* chunkAsync(source, size) {
  if (size <= 0) throw new Error('size must be positive');

  const iterator = Symbol.iterator in source ? source[Symbol.iterator]() : source[Symbol.asyncIterator]();
  let buffer = [];
  let done = false;

  try {
    while (!done) {
      if (buffer.length === 0) {
        const { value, done: d } = await iterator.next();
        if (d) {
          done = true;
          break;
        }
        buffer.push(value);
      }

      const chunk = [];
      while (chunk.length < size && buffer.length > 0) {
        chunk.push(buffer.shift());
      }
      yield chunk;
    }

    if (buffer.length > 0) {
      yield buffer;
    }
  } finally {
    if (typeof iterator.return === 'function') {
      await iterator.return();
    }
  }
}

module.exports = { chunkAsync };
