function zipLongest(fill, ...iterables) {
  if (iterables.length === 0) {
    return (function* () {})();
  }

  const iterators = iterables.map(it => it[Symbol.iterator]());
  const active = new Set(iterators);

  return (function* () {
    while (active.size > 0) {
      const row = [];
      for (const it of iterators) {
        const { value, done } = it.next();
        if (done) {
          active.delete(it);
          row.push(fill);
        } else {
          row.push(value);
        }
      }
      yield row;
    }
  })();
}

module.exports = zipLongest;
