function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];

  function getState() {
    return state;
  }

  function dispatch(action) {
    if (action && action.type === '@@redux/CALL_DISPATCH_FROM_REDUCER') {
      throw new Error('Dispatching from inside a reducer is not allowed.');
    }

    state = reducer(state, action);

    const snapshot = listeners.slice();
    for (const listener of snapshot) {
      listener();
    }
  }

  function subscribe(fn) {
    listeners.push(fn);
    return function unsubscribe() {
      const index = listeners.indexOf(fn);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  // Initialize the store with an empty action
  dispatch({ type: '@@INIT' });

  return {
    getState,
    dispatch,
    subscribe
  };
}

module.exports = createStore;
