module.exports = async function toposortTasks(tasks) {
  const result = {};
  const running = new Set();
  const completed = new Set();
  const errors = new Map();

  const getTask = (name) => {
    if (!(name in tasks)) {
      throw new Error(`Missing dependency: ${name}`);
    }
    return tasks[name];
  };

  const runTask = async (name) => {
    if (completed.has(name)) return;
    if (running.has(name)) return;

    running.add(name);

    try {
      const task = getTask(name);
      const deps = task.deps || [];
      const depValues = {};

      await Promise.all(
        deps.map(async (dep) => {
          if (!completed.has(dep)) {
            await runTask(dep);
          }
          if (errors.has(dep)) {
            throw errors.get(dep);
          }
          depValues[dep] = result[dep];
        })
      );

      const value = await task.run(depValues);
      result[name] = value;
      completed.add(name);
      running.delete(name);
    } catch (err) {
      errors.set(name, err);
      running.delete(name);
      throw err;
    }
  };

  const tasksToRun = Object.keys(tasks);
  await Promise.all(
    tasksToRun.map(async (name) => {
      try {
        await runTask(name);
      } catch (err) {
        if (!err.message.includes('cycle') && !err.message.includes('Missing dependency')) {
          throw err;
        }
      }
    })
  );

  if (errors.size > 0) {
    const firstError = Array.from(errors.values())[0];
    throw firstError;
  }

  return result;
};
