type MatchHandlers<T, K extends keyof T> = {
  [P in K]: (value: T[P]) => any;
};

function match<T, K extends keyof T>(
  value: T,
  handlers: {
    [P in K]: (value: T[P]) => any;
  }
): ReturnType<MatchHandlers<T, K>[K]> {
  const kind = value.kind;
  if (kind in handlers) {
    return handlers[kind as K](value);
  }
  throw new Error(`No handler for kind: ${String(kind)}`);
}

