export type Builder<Config extends Record<string, any>> = {
  set<K extends keyof Config>(key: K, value: Config[K]): Builder<Config>;
  build(): Config;
};

export function builder<Config extends Record<string, any>>(): Builder<Config> {
  const entries = new Map<keyof Config, Config[keyof Config]>();
  const requiredKeys = new Set<keyof Config>();

  function set<K extends keyof Config>(key: K, value: Config[K]): Builder<Config> {
    if (entries.has(key)) {
      throw new Error(`Key '${String(key)}' already set`);
    }
    entries.set(key, value);
    return this as Builder<Config>;
  }

  function build(): Config {
    const missing = requiredKeys.size > 0 ? 
      Array.from(requiredKeys).filter(k => !entries.has(k)) : [];

    if (missing.length > 0) {
      throw new Error(`Missing required keys: ${missing.map(k => String(k)).join(', ')}`);
    }

    const result = {} as Config;
    for (const [key, value] of entries.entries()) {
      result[key] = value;
    }
    return result;
  }

  return {
    set,
    build
  };
}

// Helper to define required keys
export function required<Config extends Record<string, any>>(config: Config): Config {
  const builder = builder<Config>();
  for (const key in config) {
    if (Object.prototype.hasOwnProperty.call(config, key)) {
      // Mark as required
      (builder as any).requiredKeys = (builder as any).requiredKeys || new Set();
      (builder as any).requiredKeys.add(key);
    }
  }
  return builder as unknown as Config;
}

// Usage example:
// interface MyConfig {
//   name: string;
//   age: number;
//   email?: string;
// }
//
// const config = required<MyConfig>({ name: '', age: 0 });
// const built = config.set('name', 'John').set('age', 30).build();
