// sol.ts

/**
 * A branded type utility that creates a nominal type.
 * `Brand<T, B>` is assignable only from itself, not from `T` or other brands.
 */
export type Brand<T, B> = T & { readonly __brand: B };

/**
 * The Email type is a branded string.
 * It is not assignable from a plain string.
 */
export type Email = Brand<string, 'Email'>;

/**
 * Validates if a string is a well-formed email address.
 * This is a basic regex check. For production, consider a more robust library.
 * @param s The string to validate.
 * @returns `true` if the string is a valid email, `false` otherwise.
 */
const isValidEmail = (s: string): boolean => {
  // Basic email regex pattern
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(s);
};

/**
 * Type guard to check if a value is an Email.
 * @param s The value to check.
 * @returns `true` if `s` is an Email, `false` otherwise.
 */
export const isEmail = (s: string): s is Email => {
  return isValidEmail(s);
};

/**
 * Casts a string to an Email type.
 * Throws an error if the string is not a valid email address.
 * @param s The string to cast.
 * @returns The string cast as an Email.
 * @throws {Error} If the string is not a valid email address.
 */
export const asEmail = (s: string): Email => {
  if (!isEmail(s)) {
    throw new Error(`Invalid email address: "${s}"`);
  }
  return s as Email;
};
