// sol.ts

type KeysOf<T, K extends keyof T> = K extends keyof T ? T[K] : never;

type PickType<T, K extends keyof T> = {
  [P in K]: KeysOf<T, P>;
};

type OmitType<T, K extends keyof T> = {
  [P in keyof T as P extends K ? never : P]: KeysOf<T, P>;
};

export function pick<T, K extends keyof T>(obj: T, keys: readonly K[]): PickType<T, K> {
  const result = {} as PickType<T, K>;
  for (const key of keys) {
    if (key in obj) {
      result[key] = obj[key];
    }
  }
  return result;
}

export function omit<T, K extends keyof T>(obj: T, keys: readonly K[]): OmitType<T, K> {
  const result = {} as OmitType<T, K>;
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key) && !keys.includes(key as K)) {
      result[key as keyof OmitType<T, K>] = obj[key as keyof T];
    }
  }
  return result;
}
